    acc_dtype = torch.float64 if input.dtype == torch.float64 else torch.float32
    rows_target = target.reshape(rows, classes)
    non_target = is_target.reshape(rows, classes) == 0

    # Multiplicity of each class id inside the active prefix: the entries of the
    # row up to the first -1, counted per id.
    positions = torch.arange(classes, device=target.device)
    terminated = rows_target < 0
    # The prefix ends at the first -1, or spans the row when there is none.
    stop = torch.where(
        terminated.any(dim=1),
        torch.argmax(terminated.to(torch.int64), dim=1),
        torch.full((rows,), classes, device=target.device, dtype=torch.int64),
    )
    active = positions[None, :] < stop[:, None]
    mult = torch.zeros((rows, classes), dtype=acc_dtype, device=input.device)
    # clamp (not clamp_): the ids behind the terminator are masked off by
    # ``active`` anyway, and the caller's target must not be modified.
    mult.scatter_add_(
        1,
        rows_target.clamp(min=0),
        active.to(acc_dtype),
    )

    scale = 1.0 / classes
    if reduction == 1:
        scale /= rows
    factor = grad_output.reshape(-1).to(acc_dtype)
    if factor.numel() == 1:
        factor = factor.expand(rows)

    # hinge[r, a, d] marks the surviving (target a, non-target d) pairs. The
    # margin is formed in the *input* element type, exactly as the kernel and the
    # native implementations do: the hinge is a discontinuous test, so evaluating
    # it in a wider type would flip the near-tie pairs and change the integer
    # count the gradient is built from, by far more than a rounding tolerance.
    margin_input = input.reshape(rows, classes)
    hinge = (1.0 - margin_input[:, :, None] + margin_input[:, None, :]) > 0.0
    pairs = hinge & (mult > 0)[:, :, None] & non_target[:, None, :]
    weighted = pairs.to(acc_dtype) * mult[:, :, None]
    grad = weighted.sum(dim=1) - weighted.sum(dim=2)
    grad *= (scale * factor)[:, None]
