@pytest.mark.multilabel_margin_loss_backward
@pytest.mark.parametrize("reduction", [0, 1, 2])
def test_multilabel_margin_loss_backward_scalar_grad_output(reduction):
    # A 0-dim grad_output is applied to every row, which the torch oracle in this
    # file implements and the native CUDA kernel does not: it indexes
    # grad_output per row regardless of its size, so a 0-dim argument makes it
    # read past the single element it was given -- probed on the measured target
    # by varying the memory behind such a buffer, rows 1.. of its result track
    # that padding.
    # A small batch with an odd class count keeps the comparison cheap while the
    # last 64-wide pair tile stays partial.
    shape = (8, 11)
    dtype = torch.float32
    inp = _make_input(dtype, shape, MAIN_RANGE, flag_gems.device)
    target = _make_target(shape, MAIN_PATTERN, flag_gems.device)
    ref_inp = utils.to_reference(inp)
    ref_target = utils.to_reference(target)

    _, ref_is_target = torch.ops.aten.multilabel_margin_loss_forward(
        ref_inp, ref_target, reduction
    )
    scalar_grad_output = torch.full(
        (), 0.75, dtype=ref_inp.dtype, device=ref_inp.device
    )
    ref_out = _reference(
        scalar_grad_output, ref_inp, ref_target, reduction, ref_is_target
    )

    res_out = flag_gems.multilabel_margin_loss_backward(
        scalar_grad_output.to(device=inp.device, dtype=dtype),
        inp,
        target,
        reduction,
        ref_is_target.to(device=inp.device, dtype=dtype),
    )

    utils.gems_assert_close(
        res_out, ref_out, dtype, equal_nan=True, reduce_dim=shape[-1]
    )


@pytest.mark.multilabel_margin_loss_backward
@pytest.mark.parametrize("dtype", HALF_DTYPES)
def test_multilabel_margin_loss_backward_half_dtypes(dtype):
    # Neither native backend implements Half/BFloat16, so the oracle in this file
    # is the reference. It is held in the input dtype throughout, including the
    # hinge test, which is what makes the comparison meaningful: upcasting the
    # input and comparing against that result would compare two different sets of
    # surviving pairs, not two roundings of the same one.
    # A small batch with an odd class count keeps the comparison cheap while the
    # last pair tile stays partial.
    shape = (8, 11)
    inp = _make_input(dtype, shape, MAIN_RANGE, flag_gems.device)
    target = _make_target(shape, MAIN_PATTERN, flag_gems.device)
    is_target = torch.zeros(shape, dtype=dtype, device=flag_gems.device)
    is_target[:, : max(1, shape[-1] // 2)] = 1
    grad_output = torch.full((), 0.75, dtype=dtype, device=flag_gems.device)

    res_out = flag_gems.multilabel_margin_loss_backward(
        grad_output, inp, target, 1, is_target
    )
    # The oracle is built from to_reference inputs so it lands on the reference
    # device, which is what gems_assert_close compares against; it must not be
    # upcast, or the hinge would be evaluated in the wrong element type.
    ref_out = _reference(
        utils.to_reference(grad_output),
        utils.to_reference(inp),
        utils.to_reference(target),
        1,
        utils.to_reference(is_target),
    )

    assert res_out.dtype == dtype
    utils.gems_assert_close(res_out, ref_out, dtype, reduce_dim=shape[-1])


